import type { Metadata } from 'next'
import Link from 'next/link'
import { headers } from 'next/headers'
import type { Post } from './blog/types'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: { title: 'Home - My Blog' },
}

export default async function HomePage() {
  const userAgent = (await headers()).get('user-agent') ?? ''
  const response = await fetch('https://jsonplaceholder.typicode.com/posts?_limit=5', {
    cache: 'no-store',
  })
  if (!response.ok) throw new Error('Failed to load recent posts')
  const posts: Post[] = await response.json()
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <Link href="/blog" className="button-link">View All Posts</Link>
    </div>
  )
}

