import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from './BackButton'
import type { Comment, Post } from '../types'

type Props = { params: Promise<{ id: string }> }

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const response = await fetch('https://jsonplaceholder.typicode.com/posts')
  if (!response.ok) throw new Error('Failed to load post IDs')
  const posts: Post[] = await response.json()
  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

async function getPost(id: string): Promise<Post | null> {
  const response = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  })
  if (response.status === 404) return null
  if (!response.ok) throw new Error('Failed to load post')
  const post: Post | Record<string, never> = await response.json()
  return 'id' in post ? post as Post : null
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)
  if (!post) return { title: '404 - Page Not Found' }
  const description = post.body.substring(0, 160)
  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: { title: post.title, description },
  }
}

export default async function BlogPost({ params }: Props) {
  const { id } = await params
  const post = await getPost(id)
  if (!post) notFound()

  const response = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
    next: { revalidate: 300 },
  })
  if (!response.ok) throw new Error('Failed to load comments')
  const comments: Comment[] = await response.json()

  return (
    <article>
      <BackButton />
      <h1>{post.title}</h1>
      <p>{post.body}</p>
      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

