export async function GET(_request: Request, context: RouteContext<'/api/posts/[id]'>) {
  const { id } = await context.params
  return Response.json({
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  })
}

export async function PUT(request: Request, context: RouteContext<'/api/posts/[id]'>) {
  const { id } = await context.params
  const body: unknown = await request.json()
  const { title, content }: PostInput =
    body !== null && typeof body === 'object' ? body as PostInput : {}

  return Response.json({
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  })
}

export async function DELETE(_request: Request, context: RouteContext<'/api/posts/[id]'>) {
  const { id } = await context.params
  return Response.json({ message: `Post ${id} deleted successfully` })
}

